import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { join } from "node:path";

const root = "/Users/elikafilin/Documents/home_projects/organic-shop-orchestrator/submissions/elika-filin";
const change = "add-catalog";
const caps = ["catalog-api", "catalog-web", "shop-adapters"];

function sections(md) {
  const out = {};
  let current = null;
  for (const line of md.split("\n")) {
    const m = line.match(/^## (.+?)\s*$/);
    if (m) { current = m[1]; out[current] = []; continue; }
    if (current !== null) out[current].push(line);
  }
  return Object.fromEntries(Object.entries(out).map(([k, v]) => [k, v.join("\n").replace(/^\n+/, "").replace(/\s+$/, "")]));
}

for (const cap of caps) {
  const deltaPath = join(root, "openspec/changes", change, "specs", cap, "spec.md");
  const mainDir = join(root, "openspec/specs", cap);
  const mainPath = join(mainDir, "spec.md");
  const delta = readFileSync(deltaPath, "utf8");
  const sec = sections(delta);
  const keys = Object.keys(sec);
  const allowed = ["Purpose", "ADDED Requirements"];
  const unexpected = keys.filter((k) => !allowed.includes(k));
  if (unexpected.length) throw new Error(`${cap}: unexpected delta sections ${unexpected.join(", ")}`);
  if (!sec["ADDED Requirements"]) throw new Error(`${cap}: no ADDED requirements`);
  if (existsSync(mainPath)) throw new Error(`${cap}: main spec already exists at ${mainPath}`);
  const purpose = sec["Purpose"];
  if (!purpose) throw new Error(`${cap}: delta has no Purpose`);
  const main = `# ${cap} Specification\n\n## Purpose\n\n${purpose}\n\n## Requirements\n\n${sec["ADDED Requirements"]}\n`;
  mkdirSync(mainDir, { recursive: true });
  writeFileSync(mainPath, main, "utf8");

  // verification against the canonical sync contract
  const written = readFileSync(mainPath, "utf8");
  const problems = [];
  if (!written.startsWith(`# ${cap} Specification\n`)) problems.push("title");
  if (/^## (ADDED|MODIFIED|REMOVED|RENAMED) Requirements/m.test(written)) problems.push("delta header remains");
  const wsec = sections(written);
  if (wsec["Purpose"] !== purpose) problems.push("purpose not verbatim");
  if (wsec["Requirements"] !== sec["ADDED Requirements"]) problems.push("requirements not verbatim");
  const reqNames = (s) => [...s.matchAll(/^### Requirement: (.+?)\s*$/gm)].map((m) => m[1]);
  const deltaReqs = reqNames(sec["ADDED Requirements"]);
  const mainReqs = reqNames(wsec["Requirements"]);
  const missing = deltaReqs.filter((r) => !mainReqs.includes(r));
  if (missing.length) problems.push(`missing requirements: ${missing.join(", ")}`);
  const scenarioCount = (s) => (s.match(/^#### Scenario: /gm) || []).length;
  if (scenarioCount(sec["ADDED Requirements"]) !== scenarioCount(wsec["Requirements"])) problems.push("scenario count differs");
  console.log(`${cap}: wrote ${mainPath}`);
  console.log(`  requirements (${mainReqs.length}): ${mainReqs.join(" | ")}`);
  console.log(`  scenarios: ${scenarioCount(wsec["Requirements"])}, purpose chars: ${purpose.length}`);
  console.log(`  verification: ${problems.length ? "PROBLEMS " + problems.join("; ") : "ok"}`);
}
EOF
